function stmts(string $file): array { $b = ''; $o = []; foreach (preg_split('/\R/', (string)file_get_contents($file)) as $l) { $t = trim($l); if ($b === '' && ($t === '' || str_starts_with($t, '--'))) continue; $b .= $l . "\n"; if (str_ends_with($t, ';')) { $o[] = $b; $b = ''; } } return $o; }
function run(PDO $p, string $f): void { foreach (stmts($f) as $s) $p->exec($s); } function tbls(PDO $p): array { return $p->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN); }
foreach (['aff_commission_event', 'aff_commission', 'aff_link_history', 'aff_link', 'aff_partner_history', 'aff_partner', 'aff_network'] as $t) $pdo->exec("DROP TABLE IF EXISTS $t"); aff_public_cache_clear();
