section('migration: additive, idempotent, reversible');
$before = tbls($pdo); $sum = []; foreach ($before as $t) $sum[$t] = $pdo->query("CHECKSUM TABLE `$t`")->fetch(PDO::FETCH_NUM)[1];
run($pdo, "$root/database/phase7e_affiliate.sql"); run($pdo, "$root/database/phase7e_affiliate.sql"); $new = array_values(array_diff(tbls($pdo), $before)); sort($new); ok($new === ['aff_commission', 'aff_commission_event', 'aff_link', 'aff_link_history', 'aff_network', 'aff_partner', 'aff_partner_history'], 'adds exactly seven tables');
$same = true; foreach ($before as $t) if ($pdo->query("CHECKSUM TABLE `$t`")->fetch(PDO::FETCH_NUM)[1] !== $sum[$t]) $same = false; ok($same, 'no existing table changed'); ok((int)$pdo->query('SELECT COUNT(*) FROM aff_network')->fetchColumn() === 6 && (int)$pdo->query('SELECT COUNT(*) FROM aff_partner')->fetchColumn() === 0, 'six network NAMES seeded, no partnership, link or commission invented');
$codes = $pdo->query('SELECT code FROM aff_network ORDER BY code')->fetchAll(PDO::FETCH_COLUMN); ok($codes === ['awin', 'cj', 'direct', 'impact', 'partnerstack', 'rakuten'], 'Awin, Impact, PartnerStack, CJ, Rakuten and Direct');
run($pdo, "$root/database/phase7e_rollback.sql"); ok(array_values(array_diff(tbls($pdo), $before)) === [], 'rollback removes only the new tables'); run($pdo, "$root/database/phase7e_affiliate.sql"); ok(aff_ready($pdo), 're-applies after rollback'); $nets = array_column(aff_networks($pdo), 'id', 'code');

