ok($eur && $eur['affiliate'] === 0 && $eur['series']['2026-09']['affiliate'] === 6000 && $eur['series']['2026-10']['affiliate'] === -6000, 'EUR: the paid 60.00 counts in September and its reversal subtracts in October'); ok(($usd['streams']['affiliate']['received'] ?? 0) === 12050 && ADMF_STREAMS['affiliate'] === 'Affiliate commissions (received)', 'shown as its own revenue stream');
ok($usd['invoiced'] === 0 && $usd['received'] === 0 && $usd['outstanding'] === 0, 'contract invoicing and receipts are untouched (affiliate income is never a contract payment)'); ok($usd['net_income'] === 12050 && $usd['profit'] === 12050, 'net income and profit include it once'); ok(!isset($rep['currencies']['USD']['series']['2026-10']) || $rep['currencies']['USD']['series']['2026-10']['affiliate'] === 0, 'approved and pending commissions are not income');
$only = admf_report(['affiliate' => [['currency' => 'EUR', 'amount_minor' => 5000, 'date' => '2026-11-03', 'kind' => 'received']]], '2026-11-28'); ok($only['currencies']['EUR']['ytd_income'] === 5000, 'year-to-date income includes it'); ok(admf_report(['contracts' => []], '2026-11-28')['currencies'] === [], 'reports without the affiliate key are unchanged');

section('dashboard: recorded data, zero vs unavailable');
